fn fibonacci_recursive(n: Int) -> Int {
    if n <= 1 { return n }
    return fibonacci_recursive(n - 1) + fibonacci_recursive(n - 2)
}

fn fibonacci_iterative(n: Int) -> Int {
    if n <= 1 { return n }
    let mut a = 0
    let mut b = 1
    for _ in 2..=n {
        let temp = a + b
        a = b
        b = temp
    }
    return b
}

@bench
fn bench_fib_recursive() {
    let result = fibonacci_recursive(20)
    bench::black_box(result)
}

@bench
fn bench_fib_iterative() {
    let result = fibonacci_iterative(20)
    bench::black_box(result)
}

