fn linear_search(data: &[Int], target: Int) -> Option<Int> {
    for (i, val) in data.enumerate() {
        if val == target { return Some(i) }
    }
    return None
}

fn binary_search(data: &[Int], target: Int) -> Option<Int> {
    let mut lo = 0
    let mut hi = data.len()
    while lo < hi {
        let mid = (lo + hi) / 2
        if data[mid] == target { return Some(mid) }
        if data[mid] < target { lo = mid + 1 }
        else { hi = mid }
    }
    return None
}

@bench
fn bench_linear() {
    let arr = (0..1000).collect()
    let r = linear_search(&arr, 999)
    bench::black_box(r)
}

@bench
fn bench_binary() {
    let arr = (0..1000).collect()
    let r = binary_search(&arr, 999)
    bench::black_box(r)
}
